package ai.novita.sandbox.core; public class VolumeInfo { @com.google.gson.annotations.SerializedName(value="volumeID",alternate={"volume_id","id"}) private String volumeID; private String name,token; @com.google.gson.annotations.SerializedName(value="quotaSizeGiB",alternate={"quota_size_gib"}) private long quotaSizeGiB; @com.google.gson.annotations.SerializedName(value="usedSizeBytes",alternate={"used_size_bytes"}) private long usedSizeBytes; public String getVolumeId(){return volumeID;} public String getName(){return name;} public String getToken(){return token;} public long getQuotaSizeGiB(){return quotaSizeGiB;} public long getUsedSizeBytes(){return usedSizeBytes;} }
